-- check.sql — self-check for: A procedure with a parameter on top of the view
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 3 checks ──────────';

-- CHECK 1: Department 2 returns its 4 employees
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @o TABLE (empSSN DECIMAL(18,0), empName NVARCHAR(50), empAddress NVARCHAR(100), depNum INT, depName NVARCHAR(50));
INSERT INTO @o EXEC dbo.prContactsOfDepartment 2;
SET @ok = IIF((SELECT COUNT(*) FROM @o) = 4 AND NOT EXISTS (SELECT 1 FROM @o WHERE depNum <> 2), 1, 0); SET @info = CONCAT(N''rows: '', (SELECT COUNT(*) FROM @o));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. Department 2 returns its 4 employees | Phòng 2 trả 4 nhân viên của nó'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. Department 2 returns its 4 employees | Phòng 2 trả 4 nhân viên của nó', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: An unknown department returns no rows
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @o TABLE (empSSN DECIMAL(18,0), empName NVARCHAR(50), empAddress NVARCHAR(100), depNum INT, depName NVARCHAR(50));
INSERT INTO @o EXEC dbo.prContactsOfDepartment 42;
SET @ok = IIF((SELECT COUNT(*) FROM @o) = 0, 1, 0); SET @info = CONCAT(N''rows: '', (SELECT COUNT(*) FROM @o));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. An unknown department returns no rows | Phòng không tồn tại trả không dòng'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. An unknown department returns no rows | Phòng không tồn tại trả không dòng', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: The parameter is really used (department 5 → 2 rows)
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @o TABLE (empSSN DECIMAL(18,0), empName NVARCHAR(50), empAddress NVARCHAR(100), depNum INT, depName NVARCHAR(50));
INSERT INTO @o EXEC dbo.prContactsOfDepartment 5;
SET @ok = IIF((SELECT COUNT(*) FROM @o) = 2, 1, 0); SET @info = CONCAT(N''rows: '', (SELECT COUNT(*) FROM @o));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. The parameter is really used (department 5 → 2 rows) | Tham số thật sự được dùng (phòng 5 → 2 dòng)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. The parameter is really used (department 5 → 2 rows) | Tham số thật sự được dùng (phòng 5 → 2 dòng)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

